const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Monte Pisano, Northern Italy. A buffer is used to define the area of interest.
  const aoi = ee.Geometry.Point([10.51, 43.78]).buffer(5000); // 5km buffer
  const startDate = '2019-02-24';
  const endDate = '2019-02-27'; // GEE date range is exclusive of the end date

  // 2. Data Acquisition & Check
  // Use the MODIS Thermal Anomalies & Fire collection, which is standard for active fire detection.
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  // The collection contains features for each fire detection. We can simply count them.
  const fireCount = fireCollection.size().getInfo();

  // 3. Validation & Final Answer
  console.log(`Query Period: ${startDate} to 2019-02-26`);
  console.log(`Area of Interest: Monte Pisano, Italy`);

  if (fireCount === null || fireCount === undefined) {
    console.log("Error: Failed to retrieve fire detection count.");
    console.log("A: C3");
    return;
  }

  console.log(`MODIS active fire detections: ${fireCount}`);

  if (fireCount > 0) {
    console.log("Evidence: Active fire points were detected within the specified area and time frame.");
    console.log("A");
  } else {
    console.log("Evidence: No active fire points were detected by MODIS in the area and time frame.");
    console.log("B");
  }
}

